use std::collections::HashMap;
use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut map: HashMap<i64, i64> = HashMap::new();

    if let Some(array) = input.as_array() {
        for item in array {
            if let Some(row) = item.as_array() {
                if let Some(key) = row.get(0).and_then(|v| v.as_i64()) {
                    if let Some(value) = row.get(1).and_then(|v| v.as_i64()) {
                        *map.entry(key).or_insert(0) += value;
                    }
                }
            }
        }
    }

    let mut result: Vec<Vec<i64>> = map.into_iter()
        .map(|(key, value)| vec![key, value])
        .collect();

    result.sort_by(|a, b| a[0].cmp(&b[0]));

    serde_json::Value::Array(result.into_iter().map(|v| serde_json::Value::Array(vec![
        serde_json::Value::Number(serde_json::Number::from(v[0])),
        serde_json::Value::Number(serde_json::Number::from(v[1])),
    ])).collect())
}
